// Convert chatInput to query format for TF-IDF Search
const chatInput = $input.first().json.chatInput;
return [{ json: { query: chatInput } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.documents) {
  staticData.documents = [];
}

const item = $input.first().json;
const title = item.title;
const text = item.extract;
const url = item.content_urls?.desktop?.page || '';

const exists = staticData.documents.some(d => d.title === title);
if (exists) {
  return [{
    json: {
      success: true,
      duplicate: true,
      message: `Article "${title}" already in corpus`,
      doc_count: staticData.documents.length
    }
  }];
}

staticData.documents.push({
  title,
  text,
  url,
  added: new Date().toISOString()
});

return [{
  json: {
    success: true,
    title,
    message: `Article "${title}" added to corpus`,
    doc_count: staticData.documents.length
  }
}];

const staticData = $getWorkflowStaticData('global');
const docs = staticData.documents || [];
const query = $input.first().json.body?.query || $input.first().json.query || '';

if (!query) {
  return [{ json: { error: 'Missing query parameter. Send {"query": "your question"}' } }];
}

if (docs.length === 0) {
  return [{ json: { query, answer: 'Aucun document dans le corpus. Ajoutez des articles via POST /webhook/rag-add-doc', sources: [], doc_count: 0 } }];
}

// --- TF-IDF Search ---
function tokenize(text) {
  return text.toLowerCase()
    .replace(/[^a-zà-ÿ0-9\s]/g, '')
    .split(/\s+/)
    .filter(t => t.length > 2);
}

const queryTokens = tokenize(query);
const N = docs.length;

const df = {};
docs.forEach(doc => {
  const tokens = new Set(tokenize(doc.text));
  tokens.forEach(t => { df[t] = (df[t] || 0) + 1; });
});

const scored = docs.map((doc) => {
  const tokens = tokenize(doc.text);
  const tf = {};
  tokens.forEach(t => { tf[t] = (tf[t] || 0) + 1; });

  let score = 0;
  queryTokens.forEach(qt => {
    if (tf[qt] && df[qt]) {
      const termFreq = tf[qt] / tokens.length;
      const idf = Math.log(N / df[qt]);
      score += termFreq * idf;
    }
  });

  return { title: doc.title, text: doc.text, url: doc.url, score };
});

scored.sort((a, b) => b.score - a.score);
const topDocs = scored.slice(0, 3).filter(d => d.score > 0);

// Build RAG prompt
let context = '';
if (topDocs.length === 0) {
  context = 'Aucun document pertinent trouvé dans la base.';
} else {
  topDocs.forEach((doc, i) => {
    context += `---\n[Document ${i + 1}: ${doc.title}] (score: ${doc.score.toFixed(4)})\n${doc.text}\nSource : ${doc.url}\n`;
  });
  context += '---';
}

const prompt = `Tu es un assistant RAG. Tu réponds aux questions en utilisant UNIQUEMENT le contexte fourni.\n\nContexte (${docs.length} docs, ${topDocs.length} pertinents via TF-IDF) :\n${context}\n\nQuestion : ${query}\n\nRéponds en français. Cite les documents utilisés [titre]. Si le contexte ne suffit pas, dis-le.`;

return [{ json: { query, prompt, sources: topDocs.map(d => ({ title: d.title, score: d.score, url: d.url })), doc_count: docs.length } }];

const input = $input.first().json;
const prev = $('TF-IDF Search').first().json;

const answer = input.choices?.[0]?.message?.content || 'No response from LLM';
const model = input.model || 'unknown';
const srcList = (prev.sources || []).map(s => s.title).join(', ');
const chatOutput = srcList ? `${answer}\n\n📚 Sources : ${srcList}` : answer;

return [{
  json: {
    output: chatOutput,
    query: prev.query,
    answer: answer,
    model: model,
    sources: prev.sources,
    doc_count: prev.doc_count
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.documents) {
  staticData.documents = [];
}

const item = $input.first().json;
const title = item.title;
const text = item.extract;
const url = item.content_urls?.desktop?.page || '';

const exists = staticData.documents.some(d => d.title === title);
if (!exists) {
  staticData.documents.push({
    title,
    text,
    url,
    added: new Date().toISOString()
  });
}

return [{
  json: {
    stored: title,
    total: staticData.documents.length
  }
}];
